# --- Rating Curve Logic ---
def get_rating_curve(site_id):
    url = f"https://waterdata.usgs.gov/nwisweb/get_ratings?site_no={site_id}&file_type=exsa"
    curve = [] # list of (discharge, stage)
    try:
        resp = requests.get(url)
        if resp.status_code != 200:
            return None

        lines = resp.text.splitlines()
        for line in lines:
            if line.startswith('#') or line.strip() == '':
                continue
            if line.startswith('INDEP'):
                continue

            parts = line.split()
            # INDEP SHIFT DEP
            # INDEP = Stage, DEP = Discharge
            try:
                stage = float(parts[0])
                discharge = float(parts[2])
                curve.append((discharge, stage))
            except:
                continue

    except Exception as e:
        print(f"Error fetching rating curve for {site_id}: {e}")
        return None

    # Sort by discharge just in case
    curve.sort(key=lambda x: x[0])
    return curve

def discharge_to_stage(discharge, curve):
    if not curve:
        return None

    # If discharge is below min, return min stage
    if discharge <= curve[0][0]:
        return curve[0][1]
    # If above max, extrapolate or return max? Return max for safety.
    if discharge >= curve[-1][0]:
        return curve[-1][1]

    # Binary search or linear scan
    # Linear scan is fast enough for ~1000 points
    for i in range(len(curve) - 1):
        q1, s1 = curve[i]
        q2, s2 = curve[i+1]

        if q1 <= discharge <= q2:
            # Interpolate
            if q2 == q1:
                return s1
            fraction = (discharge - q1) / (q2 - q1)
            return s1 + fraction * (s2 - s1)

    return None

